def longest_awesome_substring(s):
    n = len(s)
    best = 0
    for i in range(n):
        for j in range(i, n):
            counts = [0] * 10
            for k in range(i, j + 1):                              # recounts digit frequencies from scratch
                counts[int(s[k])] += 1
            odd_count = sum(1 for c in counts if c % 2 == 1)
            if odd_count <= 1:
                best = max(best, j - i + 1)
    return best


if __name__ == "__main__":
    print(longest_awesome_substring("3242415"))

