import java.util.*;

public class Main {
    int longestAwesome(String s) {
        int n = s.length();
        int best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                int[] counts = new int[10];
                for (int k = i; k <= j; k++) {                            // recounts digit frequencies from scratch
                    counts[s.charAt(k) - '0']++;
                }
                int oddCount = 0;
                for (int c : counts) if (c % 2 == 1) oddCount++;
                if (oddCount <= 1) best = Math.max(best, j - i + 1);
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.longestAwesome("3242415"));
    }
}

