def longest_awesome_substring(s):
    first_seen = {0: -1}                                     # bitmask 0 (all even) seen before the string starts
    mask = 0
    best = 0
    for i, ch in enumerate(s):
        digit = int(ch)
        mask ^= (1 << digit)                                       # flip this digit's parity bit
        if mask in first_seen:
            best = max(best, i - first_seen[mask])                     # all even counts in this substring
        else:
            first_seen[mask] = i
        for d in range(10):
            flipped = mask ^ (1 << d)                                    # try allowing exactly one odd digit
            if flipped in first_seen:
                best = max(best, i - first_seen[flipped])
    return best


if __name__ == "__main__":
    print(longest_awesome_substring("3242415"))

